    @skip_if_cpu
    @skip_if_not_triton
    def test_vmap_dot_decomposes_bmm(self):
        # [FUNCTION DOC] For a vmapped dot product of two vectors over a batch of 64 (which becomes
        # a batched matmul), checks for float16, bfloat16, float32 and float64 (supported ones) and
        # inner sizes 3 and 32 that the compiled result equals eager and that the generated code
        # contains neither an extern bmm call nor an aten bmm fallback, i.e. the bmm is decomposed
        # into pointwise and reduction code. On ROCm older than 7.13 with some gfx11 archs bfloat16
        # uses looser tolerances because eager is inaccurate there. Triton GPU only.
        def dot_based(a, b):
            # [FUNCTION DOC] HELPER: Return two times the dot product of a and b (added twice).
            return torch.dot(a, b) + torch.dot(a, b)

        fn = torch.vmap(dot_based)
        gcn_arch_name = (
            torch.cuda.get_device_properties(0).gcnArchName.split(":")[0]
            if TEST_WITH_ROCM
            else ""
        )
        is_gfx11_0_or_5_x = re.fullmatch(r"gfx11[05]\d", gcn_arch_name) is not None
        bmm_codegen_call = (
            "aoti_torch_cuda_bmm_out" if config.cpp_wrapper else "extern_kernels.bmm"
        )
        bmm_fallback_call = (
            'aoti_torch_call_dispatcher("aten::bmm"'
            if config.cpp_wrapper
            else "torch.ops.aten.bmm.default("
        )
        for dtype in (
            torch.float16,
            torch.bfloat16,
            torch.float32,
            torch.float64,
        ):
            if not self.is_dtype_supported(dtype):
                continue
            for k in (3, 32):
                with self.subTest(dtype=dtype, k=k):
                    a = torch.randn(64, k, device=self.device, dtype=dtype)
                    b = torch.randn(64, k, device=self.device, dtype=dtype)

                    expected = fn(a, b)
                    actual, code = run_and_get_code(
                        torch.compile(fn, fullgraph=True), a, b
                    )
                    # Workaround bf16 accuracy issue for gfx1100 root cause is incorrect calculation
                    # `expected` in eager mode that uses rocBLAS(rocblas_gemvtsm_kernel) on gfx11[0|5]x
                    # in case of usage of ROCM < 7.13
                    if (
                        TEST_WITH_ROCM
                        and _get_torch_rocm_version() < (7, 13)
                        and is_gfx11_0_or_5_x
                        and dtype == torch.bfloat16
                    ):
                        self.assertEqual(actual, expected, atol=0.05, rtol=0.1)
                    else:
                        self.assertEqual(actual, expected)
                    code_str = "\n".join(code)
                    self.assertNotIn(bmm_codegen_call, code_str)
                    self.assertNotIn(bmm_fallback_call, code_str)

    @skip_if_cpu
    @skipIfXpu(msg="CUDA codegen check")
    @skip_if_not_triton
    def test_bmm_dot_shape_decompose_threshold(self):
        # [FUNCTION DOC] Threshold on the inner size for decomposing a batched matmul with unit
        # outer dims: for inner size 32 the code must not use an extern bmm; for 33 under static
        # shapes it must use the extern bmm call (under dynamic shapes it must still not). Triton
        # GPU only; CUDA codegen check.
        def fn(a, b):
            # [FUNCTION DOC] HELPER: Return bmm of a and b.
            return torch.bmm(a, b)

        bmm_codegen_call = (
            "aoti_torch_cuda_bmm_out" if config.cpp_wrapper else "extern_kernels.bmm"
        )
        bmm_fallback_call = (
            'aoti_torch_call_dispatcher("aten::bmm"'
            if config.cpp_wrapper
            else "torch.ops.aten.bmm.default("
        )
        for k in (32, 33):
            with self.subTest(k=k):
                a = torch.randn(4, 1, k, device=self.device)
                b = torch.randn(4, k, 1, device=self.device)

                expected = fn(a, b)
                actual, code = run_and_get_code(torch.compile(fn, fullgraph=True), a, b)
                self.assertEqual(actual, expected)
                code_str = "\n".join(code)
                # In dynamic-shape clones K is symbolic, so only the static
                # test can require K=33 to use the normal bmm path.
                expect_extern_bmm = k == 33 and dynamo_config.assume_static_by_default
                if expect_extern_bmm:
                    self.assertIn(bmm_codegen_call, code_str)
                else:
                    self.assertNotIn(bmm_codegen_call, code_str)
                    self.assertNotIn(bmm_fallback_call, code_str)

    @skip_if_cpu
    @skipIfXpu(msg="CUDA codegen check")
    @skip_if_not_triton
    def test_bmm_dot_shape_dynamic_k_range_spans_decompose_threshold(self):
        # [FUNCTION DOC] With the inner dimension marked dynamic over a range (1 to 64) that spans
        # the decomposition threshold, a unit-outer-dim batched matmul must still be decomposed: no
        # extern bmm call and no aten bmm fallback in the generated code. Triton GPU only.
        def fn(a, b):
            # [FUNCTION DOC] HELPER: Return bmm of a and b.
            return torch.bmm(a, b)

        bmm_codegen_call = (
            "aoti_torch_cuda_bmm_out" if config.cpp_wrapper else "extern_kernels.bmm"
        )
        bmm_fallback_call = (
            'aoti_torch_call_dispatcher("aten::bmm"'
            if config.cpp_wrapper
            else "torch.ops.aten.bmm.default("
        )

        a = torch.randn(4, 1, 3, device=self.device)
        b = torch.randn(4, 3, 1, device=self.device)
        torch._dynamo.mark_dynamic(a, 2, min=1, max=64)
        torch._dynamo.mark_dynamic(b, 1, min=1, max=64)

        expected = fn(a, b)
        actual, code = run_and_get_code(torch.compile(fn, fullgraph=True), a, b)
        self.assertEqual(actual, expected)
        code_str = "\n".join(code)
        self.assertNotIn(bmm_codegen_call, code_str)
        self.assertNotIn(bmm_fallback_call, code_str)

