    def test_conv2d_channels_last(self):
        # [FUNCTION DOC] CPU-only 1x1 convolution under channels_last: checks three cases where
        # only the weight, only the activation, or both are channels last.
        if self.device == GPU_TYPE:
            raise unittest.SkipTest("only support cpu conv2d channels_last")

        m = torch.nn.Sequential(
            torch.nn.Conv2d(3, 3, 1, 1),
            ToTuple(),
        )
        # only weight is channels_last
        self.common(
            m.to(memory_format=torch.channels_last),
            (torch.randn([2, 3, 16, 16]),),
            check_lowp=False,
        )
        # only activation is channels_last
        self.common(
            m,
            (torch.randn([2, 3, 16, 16]).to(memory_format=torch.channels_last),),
            check_lowp=False,
        )
        # activation and weight are all channels_last
        self.common(
            m.to(memory_format=torch.channels_last),
            (torch.randn([2, 3, 16, 16]).to(memory_format=torch.channels_last),),
            check_lowp=False,
        )

    def test_conv2d_backward_channels_last(self):
        # [FUNCTION DOC] Convolution backward through the aten op with a channels-last weight and
        # all three output masks enabled; low precision off.
        def fn(grad_output, inp, weight):
            # [FUNCTION DOC] HELPER: Call the aten convolution backward with bias size 320, unit
            # stride, no padding, dilation 1, and gradient masks for input, weight and bias.
            convolution_backward_8 = torch.ops.aten.convolution_backward.default(
                grad_output,
                inp,
                weight,
                [320],
                [1, 1],
                [0, 0],
                [1, 1],
                False,
                [0, 0],
                1,
                [True, True, True],
            )
            return convolution_backward_8

        # only weight is channels_last
        self.common(
            fn,
            (
                torch.randn([2, 320, 8, 8]),
                torch.randn([2, 2048, 8, 8]),
                torch.randn([320, 2048, 1, 1]).to(memory_format=torch.channels_last),
            ),
            check_lowp=False,
        )

    @skip_if_cpu
    @config.patch(
        {
            "max_autotune": True,
            "max_autotune_conv_bwd_weight_backends": "TRITON",
            "max_autotune_conv_bwd_input_backends": "TRITON",
        }
    )
    @parametrize("dilation", (1, 2))
    @parametrize("stride", (1, 2))
    @parametrize("padding", (0, 1))
    @parametrize("kernel", (1, 3))
    @parametrize(
        "channels_groups",
        (
            [3, 4, 1],
            [4, 128, 1],
            [4, 128, 4],
            [61, 151, 1],
            [128, 128, 1],
            [128, 128, 128],
        ),
    )
    @parametrize("nhwc", (False, True))
    @with_tf32_off
    @skipIfRocmVersionAtLeast(
        [7, 14]
    )  # ROCm 7.14+ Triton conv2d backward accuracy issue in this UT family
    def test_conv2d_backward_parametrized(
        self,
        channels_groups: list,
        stride: int,
        dilation: int,
        padding: int,
        kernel: int,
        nhwc: bool,
    ):
        # [FUNCTION DOC] Parametrized conv2d backward with Triton as the backend for weight and
        # input gradients under max-autotune; varies dilation, stride, padding, kernel size,
        # channel and group configurations, and NHWC weights. Output spatial sizes are derived from
        # the input size 16. Uses float32 (float16 with a looser tolerance on some ROCm Navi
        # archs). Skipped on CPU, on ROCm 7.14 and later, and under the subprocess compile mode
        # (TF32 settings are not propagated). TF32 is turned off.
        in_channels = channels_groups[0]
        out_channels = channels_groups[1]
        groups = channels_groups[2]

        if torch._inductor.compile_fx.fx_compile_mode == FxCompileMode.SUBPROCESS:
            # TODO: Remove this workaround once TF32 settings are properly passed to subprocess
            # Currently, subprocess mode starts with default TF32 settings (cudnn.allow_tf32=True)
            # even if parent process has set allow_tf32=False.
            self.skipTest("Expected failure under subprocess compile mode")

        def fn(grad_output, inp, weight):
            # [FUNCTION DOC] HELPER: Call the aten convolution backward with the parametrized
            # stride, padding, dilation and group count and all gradient masks enabled.
            conv_backward = torch.ops.aten.convolution_backward.default(
                grad_output,
                inp,
                weight,
                [out_channels],
                [stride, stride],
                [padding, padding],
                [dilation, dilation],
                False,
                [0, 0],
                groups,
                [True, True, True],
            )
            return conv_backward

        input_h = 16
        input_w = 16
        output_h = (input_h + 2 * padding - dilation * (kernel - 1) - 1) // stride + 1
        output_w = (input_w + 2 * padding - dilation * (kernel - 1) - 1) // stride + 1

        dtype = torch.float32
        use_fp16 = False
        rtol = 0.001
        if TEST_WITH_ROCM:
            # using the same error tolerance as test_convolution1.
            atol = 6e-5
            if isRocmArchAnyOf(NAVI_ARCH):
                use_fp16 = True
                dtype = torch.float16
                atol = 3e-1
        else:
            # Greatest absolute difference: 0.00027943775057792664 at index (92, 109, 0, 0) (up to 0.0002 allowed)
            # Greatest relative difference: 0.007547957822680473 at index (92, 109, 0, 0) (up to 0.001 allowed)
            atol = 3e-4

        weight = torch.randn(
            [out_channels, in_channels // groups, kernel, kernel], dtype=dtype
        )
        if nhwc:
            weight = weight.to(memory_format=torch.channels_last)
        self.common(
            fn,
            (
                torch.randn([2, out_channels, output_h, output_w], dtype=dtype),
                torch.randn([2, in_channels, input_h, input_w], dtype=dtype),
                weight,
            ),
            atol=atol,
            rtol=rtol,
            check_lowp=False,
            reference_in_float=not use_fp16,
        )

    @skip_if_cpu
    @skipIfRocm  # Triton conv backward kernels stay enabled on ROCm
    @config.patch(
        {
            "max_autotune": True,
            "max_autotune_conv_bwd_weight_backends": "TRITON",
            "max_autotune_conv_bwd_input_backends": "TRITON",
        }
    )
    def test_conv2d_backward_triton_disabled(self):
        # [FUNCTION DOC] On NVIDIA CUDA the Triton conv backward kernels are force-disabled (issue
        # 187081), so even with Triton requested the lowering must fall back to ATEN: the generated
        # code must not contain the triton template kernel for convolution backward and must
        # contain the aten convolution backward call (spelling depends on the wrapper). CUDA only;
        # skipped on CPU and ROCm.
        # On NVIDIA CUDA the Triton conv backward kernels hit a ptxas illegal
        # memory access (#187081) and are force-disabled; even when TRITON is
        # requested the lowering must fall back to ATEN. Assert the Triton
        # kernels are not emitted -- a numeric/IMA check would be flaky since
        # the out-of-bounds read only faults when it lands in unmapped memory.
        if self.device != "cuda":
            self.skipTest("CUDA-only behavior")

        def fn(grad_output, inp, weight):
            # [FUNCTION DOC] HELPER: Call the aten convolution backward with dilation 2, padding 1
            # and masks for input and weight only.
            return torch.ops.aten.convolution_backward.default(
                grad_output,
                inp,
                weight,
                [4],
                [1, 1],
                [1, 1],
                [2, 2],
                False,
                [0, 0],
                1,
                [True, True, False],
            )

        inps = (
            torch.randn([2, 4, 18, 18], device=self.device),
            torch.randn([2, 3, 16, 16], device=self.device),
            torch.randn([4, 3, 1, 1], device=self.device),
        )
        _, code = run_and_get_code(torch.compile(fn), *inps)
        code = "".join(code)
        # Without the fix a triton_tem_fused_convolution_backward template
        # kernel is emitted; with the fix the lowering falls back to ATEN. The
        # ATEN call spelling depends on the wrapper: the Python wrapper emits
        # torch.ops.aten.convolution_backward, the C++/AOTI wrapper emits
        # aoti_torch_cuda_convolution_backward.
        self.assertNotIn("triton_tem_fused_convolution_backward", code)
        self.assertTrue(
            "torch.ops.aten.convolution_backward.default(" in code
            or "aoti_torch_cuda_convolution_backward(" in code,
            "expected conv backward to fall back to ATEN",
        )

    @skip_if_cpu
    @config.patch(
        {
            "max_autotune": True,
            "max_autotune_conv_backends": "TRITON",
        }
    )
    @parametrize("dilation", (1, 2))
    @parametrize("stride", (1, 2))
    @parametrize("padding", (0, 1))
    @parametrize("kernel", (1, 3))
    @parametrize(
        "channels_groups",
        (
            [3, 4, 1],
            [4, 128, 1],
            [4, 128, 4],
            [128, 128, 1],
        ),
    )
    @parametrize("nhwc", (False, True))
    @with_tf32_off
    def test_conv_transpose2d_forward_triton(
        self,
        channels_groups: list,
        stride: int,
        dilation: int,
        padding: int,
        kernel: int,
        nhwc: bool,
    ):
        # [FUNCTION DOC] Parametrized transposed 2-D convolution forward using Triton under
        # max-autotune; varies stride, dilation, padding, kernel, channel/group configuration and
        # NHWC layout. Skipped on CPU, under dynamic shapes (known codegen failure) and under the
        # subprocess compile mode. TF32 off.
        in_channels = channels_groups[0]
        out_channels = channels_groups[1]
        groups = channels_groups[2]

        if is_dynamic_shape_enabled():
            self.skipTest("Expected codegen failure under dynamic shapes")

        if torch._inductor.compile_fx.fx_compile_mode == FxCompileMode.SUBPROCESS:
            self.skipTest("Expected failure under subprocess compile mode")

        def fn(x, weight):
            # [FUNCTION DOC] HELPER: Call the aten transposed convolution with the parametrized
            # options and no bias.
            return torch.ops.aten.convolution(
                x,
                weight,
                None,
                [stride, stride],
                [padding, padding],
                [dilation, dilation],
                True,
                [0, 0],
                groups,
            )

        input_h = 8
        input_w = 8

        atol = 2e-4
        rtol = 0.001

        weight = torch.randn([in_channels, out_channels // groups, kernel, kernel])
        x = torch.randn([2, in_channels, input_h, input_w])
        if nhwc:
            weight = weight.to(memory_format=torch.channels_last)
            x = x.to(memory_format=torch.channels_last)
        self.common(
            fn,
            (x, weight),
            atol=atol,
            rtol=rtol,
            check_lowp=False,
        )

