    def test_searchsorted(self):
        # [FUNCTION DOC] searchsorted over shapes (scalar-like sequence, scalar values, 1-D, N-D,
        # prime sized) and all combinations of int32 output and right flag: once with a sorted
        # sequence and no sorter, and once with an unsorted sequence plus the sorter indices; side
        # string is derived from the right flag. Low precision check off.
        def fn(sorted_sequence, values, out_int32, right, side, sorter):
            # [FUNCTION DOC] HELPER: Call torch searchsorted with all the given options.
            return torch.searchsorted(
                sorted_sequence,
                values,
                out_int32=out_int32,
                right=right,
                side=side,
                sorter=sorter,
            )

        shapes = (
            ((1,), (16, 16)),  # scalar sorted_sequence
            ((16,), ()),  # scalar values
            ((32,), (16, 16)),  # 1-D sorted_sequence
            ((16, 32), (16, 16)),  # N-D sorted_sequence
            ((3, 5), (3, 7)),  # prime dimensioned sequence, to flush out indexing bugs
        )
        booleans = (False, True)

        for (seq_shape, value_shape), out_int32, right in itertools.product(
            shapes, booleans, booleans
        ):
            unsorted_sequence = torch.rand(seq_shape)
            sorted_sequence, sorting_indices = torch.sort(unsorted_sequence)
            values = torch.rand(value_shape)

            side = "right" if right else "left"
            self.common(
                fn,
                (sorted_sequence, values, out_int32, right, side, None),
                check_lowp=False,
            )
            self.common(
                fn,
                (
                    unsorted_sequence,
                    values,
                    out_int32,
                    right,
                    side,
                    sorting_indices,
                ),
                check_lowp=False,
            )

    @requires_gpu()
    @skip_if_gpu_halide
    @skip_if_not_triton
    def test_searchsorted_broadcast(self):
        # [FUNCTION DOC] On GPU with triton, searchsorted followed by unsqueeze, expand and
        # contiguous must keep bucketize separate from the broadcast (not fused, since bucketize is
        # expensive): the generated code must contain two triton kernels. Also compares numerics.
        def fn(sorted_sequence, values):
            # [FUNCTION DOC] HELPER: Search values in the sorted sequence, add a trailing dim and
            # expand to 64 along it and make contiguous.
            return (
                torch.searchsorted(
                    sorted_sequence,
                    values,
                )
                .unsqueeze(-1)
                .expand(-1, 64)
                .contiguous()
            )

        unsorted_sequence = torch.rand((32,))
        sorted_sequence, sorting_indices = torch.sort(unsorted_sequence)
        values = torch.rand((64,))

        self.common(fn, (sorted_sequence, values), check_lowp=False)
        cfn = torch.compile(fn)
        _, code = run_and_get_code(
            cfn, sorted_sequence.to(GPU_TYPE), values.to(GPU_TYPE)
        )

        # make sure that we did not fuse the broadcast and the bucketize,
        # because bucketize is computationally expensive.
        FileCheck().check("def triton").check("def triton").run(code[0])

