    @torch._inductor.config.patch("graph_partition", True)
    def test_graph_partition_both_scalars(self):
        # [FUNCTION DOC] Graph partition with two Python scalar inputs through aten arithmetic ops.
        def fn(a, b):
            # [FUNCTION DOC] HELPER: Return add, sub and mul of a and b in both orders.
            return (
                aten.add(a, b),
                aten.add(b, a),
                aten.sub(a, b),
                aten.sub(b, a),
                aten.mul(a, b),
                aten.mul(b, a),
            )

        compiled_fn = torch.compile(fn)

        self.assertEqual(fn(4, 3.3), compiled_fn(4, 3.3))

    @torch._inductor.config.patch("graph_partition", True)
    @config.patch(assume_aligned_inputs=False)
    def test_graph_partition_misaligned_input(self):
        # [FUNCTION DOC] Graph partition with misaligned inputs: reduce-overhead dynamic
        # compilation on strided views with different offsets, comparing outputs and base tensor
        # gradients with eager.
        def fn(x):
            # [FUNCTION DOC] HELPER: Return cos of x times sin of x.
            return x.cos() * x.sin()

        fn_c = torch.compile(fn, mode="reduce-overhead", dynamic=True)

        for size, stride, offset in (
            ((32, 32), (32, 1), 4),
            ((48, 48), (48, 1), 4),
            ((64, 64), (64, 1), 5),
        ):
            torch.manual_seed(42)
            base = torch.randn(
                64 * 64 + 64,
                dtype=torch.float32,
                device=self.device,
                requires_grad=True,
            )
            torch.manual_seed(42)
            base_ref = torch.randn(
                64 * 64 + 64,
                dtype=torch.float32,
                device=self.device,
                requires_grad=True,
            )

            inp = torch.as_strided(base, size, stride, offset)
            inp_ref = torch.as_strided(base_ref, size, stride, offset)

            inp.requires_grad_(True)
            inp_ref.requires_grad_(True)

            res = fn_c(inp)
            ref = fn(inp_ref)
            self.assertEqual(ref, res)

            res.sum().backward()
            ref.sum().backward()
            self.assertEqual(base.grad, base_ref.grad)

